SELECT

FROM WithdrawalHistory a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.currency = #{currency}


    AND a.blockchain = #{blockchain}


    AND a.fromAddress = #{fromAddress}


    AND a.toAddress = #{toAddress}


    AND a.amount = #{amount}


    AND a.fee = #{fee}


    AND a.transId = #{transId}


    AND a.state = #{state}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}


    AND a.checkBy = #{checkBy}


    AND a.checkTime = #{checkTime}

limit 1

SELECT

FROM WithdrawalHistory a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.currency LIKE CONCAT('%',#{currency}, '%')


    AND a.blockchain LIKE CONCAT('%',#{blockchain}, '%')


    AND a.fromAddress LIKE CONCAT('%',#{fromAddress}, '%')


    AND a.toAddress LIKE CONCAT('%',#{toAddress}, '%')


    AND a.amount = #{amount}


    AND a.fee = #{fee}


    AND a.transId LIKE CONCAT('%',#{transId}, '%')


    AND a.state LIKE CONCAT('%',#{state}, '%')


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateBy LIKE CONCAT('%',#{updateBy}, '%')


    AND a.updateTime = #{updateTime}


    AND a.checkBy LIKE CONCAT('%',#{checkBy}, '%')


    AND a.checkTime = #{checkTime}
